import { Cloud, RefreshCw } from 'lucide-react';
import { ArrowUpRight, ArrowRight, ArrowLeft, Plus, Compass, MapPin, Mountain, Coffee, Camera, Search, Heart, X, CalendarDays, BookOpen, Map as MapIcon, Stamp, SlidersHorizontal, Upload, Trash2, Pencil, ChevronLeft, ChevronRight, Check, Download, Shuffle, LockKeyhole, Menu, Grid2X2, List, LocateFixed, ImagePlus, LoaderCircle, Footprints, MoveUp, MoveDown, Star, Globe2, Sparkles, ChevronDown } from 'lucide-react';

type Category='Trekking'|'Roaming'|'Food & cafés';
type Mood='Adventure'|'Peaceful'|'With friends'|'Solo'|'Food hunt';
export type Photo={id:string;caption:string;url?:string;file?:File};
export type Entry={id:string;title:string;location:string;country:string;date:string;category:Category;mood:Mood;story:string;trip:string;rating:number;cost:string;favorite:boolean;lat:number|null;lng:number|null;photos:Photo[]};
type GalleryValue={entry:Entry;index:number;items?:AlbumPhoto[];title?:string};
const categories:Category[]=['Trekking','Roaming','Food & cafés'];
const moods:Mood[]=['Adventure','Peaceful','With friends','Solo','Food hunt'];
const catIcons={Trekking:Mountain,Roaming:Camera,'Food & cafés':Coffee};
export const sample:Entry[]=[
 {id:'sample-1',title:'A little closer to the sky',location:'Annapurna Base Camp',country:'Nepal',date:'2026-04-18',category:'Trekking',mood:'Adventure',trip:'Into the Himalayas',rating:5,cost:'',favorite:true,lat:28.5303,lng:83.878,story:'We started before the sun. Just the sound of our boots, the cold air, and the promise of something beautiful around the next bend.\n\nBy the time the mountains turned gold, we had forgotten how tired we were. We sat with warm tea in our hands and watched the light move across the peaks. No photograph quite holds a morning like that. But this one comes close.\n\nA reminder to take the slower trail. To look up. To keep a little room for wonder.',photos:[{id:'s1',caption:'The kind of morning you carry home.',url:'/photos/trek.jpg'},{id:'s2',caption:'A little perspective.',url:'/photos/mountain.jpg'}]},
 {id:'sample-2',title:'Lost in the right direction',location:'Kathmandu',country:'Nepal',date:'2026-04-12',category:'Roaming',mood:'With friends',trip:'A Kathmandu kind of day',rating:4,cost:'',favorite:false,lat:27.7172,lng:85.324,story:'No itinerary. Just a turn down a small street, another courtyard, and the smell of incense in the afternoon air.\n\nWe found the loveliest corners by giving ourselves permission to get a little lost. Stopped for tea. Watched the city move around us. Some days, wandering is the whole plan.',photos:[{id:'s3',caption:'Old streets, new stories.',url:'/photos/city.jpg'}]},
 {id:'sample-3',title:'One more cup, please',location:'Lakeside, Pokhara',country:'Nepal',date:'2026-04-09',category:'Food & cafés',mood:'Peaceful',trip:'Slow days in Pokhara',rating:5,cost:'NPR 650',favorite:true,lat:28.2096,lng:83.9595,story:'A quiet table by the window. A very good coffee. A conversation that stretched all the way into the afternoon.\n\nTravel is also this: finding a small place that makes you feel at home, even when you are far from it. Would absolutely come back for another cup.',photos:[{id:'s4',caption:'A good place to stay a little longer.',url:'/photos/cafe.jpg'}]}
];
