sample[2].photos.push({id:'s7',caption:'Illustrative sample: a slow morning and a warm cup.',url:'/photos/coffee.jpg'},{id:'s8',caption:'Illustrative sample: something delicious along the way.',url:'/photos/food.jpg'});
sample.push(
 {...sample[0],id:'sample-4',title:'The trail, a second time',date:'2025-11-10',favorite:false,story:'A sample return visit to show how Wanderbook collects photographs from the same place into one album. Every journey leaves another page.\n\nThese photographs are illustrative sample images.',photos:[{id:'s9',caption:'Illustrative sample: back where the air feels different.',url:'/photos/valley.jpg'},{id:'s10',caption:'Illustrative sample: one more reason to take the trail.',url:'/photos/trek.jpg'}]},
 {...sample[0],id:'sample-5',title:'A greener kind of quiet',location:'Shivapuri',date:'2026-05-21',trip:'Among the trees',mood:'Peaceful',lat:27.808,lng:85.385,story:'A sample woodland escape: walking slowly, looking closely, and leaving the day a little lighter.\n\nThese photographs illustrate the feeling of a forest adventure and are not location-verified photographs.',photos:[{id:'s11',caption:'Illustrative sample: light finding its way through the trees.',url:'/photos/forest.jpg'},{id:'s12',caption:'Illustrative sample: a quiet encounter in the woods.',url:'/photos/wildlife.jpg'},{id:'s13',caption:'Illustrative sample: a path made for wandering.',url:'/photos/trek.jpg'}]},
 {...sample[1],id:'sample-6',title:'Nowhere to be but here',location:'Phewa Lake',date:'2026-06-14',trip:'Slow days in Pokhara',mood:'Peaceful',lat:28.215,lng:83.945,story:'A sample lakeside afternoon. Take the long way around. Find a quiet corner. Watch the water change with the light.\n\nThese photographs are illustrative sample landscapes.',photos:[{id:'s14',caption:'Illustrative sample: the world reflected back.',url:'/photos/lake.jpg'},{id:'s15',caption:'Illustrative sample: a little blue, a little stillness.',url:'/photos/lakeside.jpg'},{id:'s16',caption:'Illustrative sample: the scenic route home.',url:'/photos/valley.jpg'}]},
 {...sample[0],id:'sample-7',title:'For the light at the end of the day',location:'Nagarkot',date:'2026-07-02',trip:'A weekend above the city',mood:'With friends',lat:27.718,lng:85.521,story:'A sample evening among the hills. A few friends, a few stories, and a horizon that makes you stay a little longer.\n\nThese photographs are illustrative sample images.',photos:[{id:'s17',caption:'Illustrative sample: a little more perspective.',url:'/photos/mountain.jpg'},{id:'s18',caption:'Illustrative sample: when the stars take over.',url:'/photos/night-sky.jpg'},{id:'s19',caption:'Illustrative sample: the quiet way back.',url:'/photos/forest.jpg'}]}
);
const image=(e:Entry,p=e.photos[0])=>p?(p.url?assetUrl(p.url):`/api/photos/${e.id}/${p.id}`):assetUrl('/photos/mountain.jpg');
const dateLabel=(d:string,full=false)=>new Date(d+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:full?'long':'short',year:'numeric'});
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kathmandu',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function fresh():Entry{return {id:crypto.randomUUID(),title:'',location:'',country:'',date:today(),category:'Trekking',mood:'Adventure',story:'',trip:'',rating:0,cost:'',favorite:false,lat:null,lng:null,photos:[]}}

const noStarterAlbums:AlbumFolder[]=[];
export default function Journal({signedIn,name,repository,starterAlbums=noStarterAlbums}:{signedIn:boolean;name:string;repository?:JournalRepository;starterAlbums?:AlbumFolder[]}){
 const [entries,setEntries]=useState<Entry[]>([]),[demo,setDemo]=useState(true),[loading,setLoading]=useState(true),[error,setError]=useState('');
 const [tab,setTab]=useState('Journal'),[category,setCategory]=useState('All moments'),[query,setQuery]=useState(''),[mood,setMood]=useState('All moods'),[sort,setSort]=useState('newest'),[onlyFav,setOnlyFav]=useState(false),[layout,setLayout]=useState('grid'),[filters,setFilters]=useState(false);
 const [selected,setSelected]=useState<Entry|null>(null),[editor,setEditor]=useState<Entry|null>(null),[lightbox,setLightbox]=useState<GalleryValue|null>(null),[toast,setToast]=useState(''),[busy,setBusy]=useState(false),[mobile,setMobile]=useState(false);
 const [albumKey,setAlbumKey]=useState<string|null>(null);
 const [sharing,setSharing]=useState<AlbumFolder|null>(null);
 const [folders,setFolders]=useState<AlbumFolder[]>([]),[creatingAlbum,setCreatingAlbum]=useState(false),[photoFirst,setPhotoFirst]=useState(false);
 const [syncing,setSyncing]=useState(false),[transfer,setTransfer]=useState(false),[backupReady,setBackupReady]=useState(false),[restoring,setRestoring]=useState(false);
 const syncRevision=useRef(0),syncRequest=useRef(false);
 const linkedAlbumOpened=useRef(false);
 const [storyKey,setStoryKey]=useState<string|null>(null),[seenStories,setSeenStories]=useState<Record<string,string>>({});
 useEffect(()=>{try{const saved=JSON.parse(localStorage.getItem('wanderbook-story-seen')||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))setSeenStories(Object.fromEntries(Object.entries(saved).filter(([,value])=>typeof value==='string')) as Record<string,string>)}catch{}},[]);
 const markStorySeen=(album:ReturnType<typeof groupPlaceAlbums>[number])=>setSeenStories(previous=>{const updated={...previous,[album.key]:storyStamp(album)};try{localStorage.setItem('wanderbook-story-seen',JSON.stringify(updated))}catch{}return updated});
 const [backup,setBackup]=useState(false);const importRef=useRef<HTMLInputElement>(null);
 const notify=(message:string)=>setToast(message);
 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),4200);return()=>clearTimeout(t)},[toast]);
 const readJournal=useCallback(async()=>{
  if(!repository){const [data,savedFolders]=await Promise.all([cloudJournal.list(),cloudJournal.listAlbums()]);return {data,allFolders:mergeAlbumFolders(savedFolders,starterAlbums)}}
  const data=await repository.list();let savedFolders:AlbumFolder[]=[];
  try{const stored=JSON.parse(localStorage.getItem('wanderbook-albums')||'[]');if(Array.isArray(stored))savedFolders=mergeAlbumFolders(stored)}catch{}
  return {data,allFolders:mergeAlbumFolders(savedFolders,starterAlbums)};
 },[repository,starterAlbums]);
 useEffect(()=>{let alive=true;if(!signedIn){setLoading(false);return}readJournal().then(({data,allFolders})=>{if(alive){setFolders(allFolders);setEntries(data);setDemo(data.length===0&&allFolders.length===0&&localStorage.getItem('wanderbook-view')!=='mine');setError('')}}).catch(e=>alive&&setError(e.message)).finally(()=>alive&&setLoading(false));return()=>{alive=false}},[signedIn,readJournal]);
 const refreshCloud=useCallback(async()=>{
  if(repository||!signedIn||syncRequest.current)return;
  syncRequest.current=true;setSyncing(true);const revision=syncRevision.current;
  try{const {data,allFolders}=await readJournal();if(revision===syncRevision.current){setEntries(data);setFolders(allFolders);setError('')}}catch(err){setError((err as Error).message)}finally{syncRequest.current=false;setSyncing(false)}
 },[repository,signedIn,readJournal]);
 useEffect(()=>{
  if(repository||!signedIn||loading||editor||backup||busy||creatingAlbum)return;
  const refresh=()=>{if(!document.hidden)void refreshCloud()};
  const timer=window.setInterval(refresh,30000);
  window.addEventListener('focus',refresh);window.addEventListener('online',refresh);document.addEventListener('visibilitychange',refresh);
  return()=>{clearInterval(timer);window.removeEventListener('focus',refresh);window.removeEventListener('online',refresh);document.removeEventListener('visibilitychange',refresh)};
 },[repository,signedIn,loading,editor,backup,busy,creatingAlbum,refreshCloud]);
 useEffect(()=>{if(repository||!signedIn||loading)return;const url=new URL(window.location.href);if(url.searchParams.get('restore')==='1'){setRestoring(true);url.searchParams.delete('restore');window.history.replaceState(null,'',url.href)}},[repository,signedIn,loading]);
 const source=demo?sample:entries;
 const albums=useMemo(()=>groupPlaceAlbums(source,demo?[]:folders),[source,demo,folders]);
 useEffect(()=>{if(loading||linkedAlbumOpened.current)return;linkedAlbumOpened.current=true;const place=new URLSearchParams(window.location.search).get('album');if(place){const album=albums.find(a=>a.place.toLocaleLowerCase('en')===place.toLocaleLowerCase('en'));if(album)setAlbumKey(album.key)}},[loading,albums]);
 const openAlbum=albums.find(album=>album.key===albumKey);
 const filtered=useMemo(()=>source.filter(e=>(category==='All moments'||e.category===category)&&(!onlyFav||e.favorite)&&(mood==='All moods'||e.mood===mood)&&[e.title,e.location,e.country,e.trip,e.story].join(' ').toLowerCase().includes(query.toLowerCase())).sort((a,b)=>sort==='oldest'?a.date.localeCompare(b.date):sort==='title'?a.title.localeCompare(b.title):b.date.localeCompare(a.date)),[source,category,onlyFav,mood,query,sort]);
 const countries=[...new Set(source.map(e=>e.country).filter(Boolean))];const places=[...new Set(source.map(e=>e.location))];const photoCount=source.reduce((sum,e)=>sum+e.photos.length,0);
 const switchDemo=(value:boolean)=>{setStoryKey(null);setDemo(value);localStorage.setItem('wanderbook-view',value?'sample':'mine');setCategory('All moments');setQuery('');setOnlyFav(false);setMood('All moods')};
 const newMemory=()=>{if(!signedIn){window.location.href='/signin-with-chatgpt?return_to=/';return}setPhotoFirst(false);setStoryKey(null);setAlbumKey(null);setSelected(null);setEditor(fresh())};
 const addAlbumPhotos=(album:PlaceAlbum)=>{if(!signedIn){newMemory();return}setPhotoFirst(true);setStoryKey(null);setAlbumKey(null);setSelected(null);setEditor({...fresh(),title:album.place.slice(0,120),location:album.place,country:album.country})};
 const storeFolders=async(next:AlbumFolder[])=>{syncRevision.current++;if(repository)localStorage.setItem('wanderbook-albums',JSON.stringify(next));else for(const folder of next)if(!folders.some(saved=>albumKeyFor(saved.place,saved.country)===albumKeyFor(folder.place,folder.country)))await cloudJournal.saveAlbum(folder);setFolders(next)};
 const createAlbum=async(folder:AlbumFolder)=>{await storeFolders(mergeAlbumFolders(folders,[folder]));switchDemo(false);setCreatingAlbum(false);const existing=groupPlaceAlbums(entries,[folder]).find(a=>a.place.toLocaleLowerCase('en')===folder.place.toLocaleLowerCase('en')&&(!folder.country||a.country===folder.country));setAlbumKey(existing?.key||albumKeyFor(folder.place,folder.country))};
 const persist=async(e:Entry)=>{syncRevision.current++;try{return await (repository||cloudJournal).save(e)}finally{syncRevision.current++}};
 const save=async(e:Entry)=>{const result=await persist(e);setEntries(prev=>[result,...prev.filter(x=>x.id!==result.id)]);if(selected?.id===e.id)setSelected(result);switchDemo(false);setEditor(null);if(photoFirst)setAlbumKey(albumKeyFor(result.location,result.country));notify(photoFirst?'Photos added to '+result.location+'.':'Memory tucked away. Here’s to the next one!')};
 const favorite=async(e:Entry)=>{if(e.id.startsWith('sample')){notify('Sample memories are a preview. Add your own to start collecting favorites.');return}try{const result=await persist({...e,favorite:!e.favorite});setEntries(prev=>prev.map(x=>x.id===e.id?result:x));if(selected?.id===e.id)setSelected(result)}catch(err){notify((err as Error).message)}};
 const remove=async(e:Entry)=>{setBusy(true);syncRevision.current++;try{await (repository||cloudJournal).remove(e.id);setEntries(prev=>prev.filter(x=>x.id!==e.id));setSelected(null);notify('Memory deleted.')}catch(err){notify((err as Error).message)}finally{syncRevision.current++;setBusy(false)}};
 const exportJournal=async()=>{setBackup(true);try{const data=await Promise.all(entries.map(async e=>({...e,photos:await Promise.all(e.photos.map(async p=>{const r=await fetch(image(e,p));if(!r.ok)throw Error('A photo could not be backed up.');const blob=await r.blob();const dataUrl=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=reject;reader.readAsDataURL(blob)});return {id:p.id,caption:p.caption,dataUrl}}))})));const url=URL.createObjectURL(new Blob([JSON.stringify({app:'wanderbook',version:1,albums:folders,entries:data})],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`wanderbook-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Your journal and photos have been backed up.');return true}catch(err){notify((err as Error).message);return false}finally{setBackup(false)}};
 const importJournal=async(file:File)=>{setBackup(true);let count=0;try{if(file.size>150*1024*1024)throw Error('Choose a backup smaller than 150 MB.');const data=JSON.parse(await file.text());if(data.app!=='wanderbook'||data.version!==1||!Array.isArray(data.entries)||data.entries.length>500)throw Error('This is not a supported Wanderbook backup.');const restoredFolders=data.albums===undefined?[]:Array.isArray(data.albums)?mergeAlbumFolders(data.albums):null;if(!restoredFolders)throw Error('The backup contains an invalid album list.');await storeFolders(mergeAlbumFolders(folders,restoredFolders));for(const original of data.entries){const e={...original,id:restoring&&/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(original.id)?original.id:crypto.randomUUID(),photos:[] as Photo[]};for(const p of original.photos||[]){if(typeof p.dataUrl!=='string'||!/^data:image\/(jpeg|png|webp|avif);base64,/.test(p.dataUrl))throw Error('The backup contains an unsupported photo.');const blob=await (await fetch(p.dataUrl)).blob();e.photos.push({id:restoring&&/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(p.id)?p.id:crypto.randomUUID(),caption:p.caption||'',file:new File([blob],'memory.jpg',{type:blob.type})})}const result=await persist(e);setEntries(prev=>[result,...prev.filter(saved=>saved.id!==result.id)]);count++}switchDemo(false);setRestoring(false);notify(restoring?`${count} memories uploaded. Open this cloud journal on your other devices.`:`${count} memories restored as new entries.`)}catch(err){notify(`${count?`${count} memories restored. `:''}${(err as Error).message}`)}finally{setBackup(false);if(importRef.current)importRef.current.value=''}};
 const navigate=(value:string)=>{setTab(value);setMobile(false);requestAnimationFrame(()=>{if(value==='Journal')window.scrollTo({top:0,behavior:'smooth'});else document.getElementById('collection')?.scrollIntoView({behavior:'smooth',block:'start'})})};
 const browseAlbums=()=>{setTab('Journal');requestAnimationFrame(()=>document.getElementById('place-albums')?.scrollIntoView({behavior:'smooth',block:'start'}))};

 return <>
 <header className="site-header"><a className="brand" href="#" onClick={()=>navigate('Journal')} aria-label="Wanderbook home"><span className="brand-icon"><Compass size={24} strokeWidth={1.5}/></span><span className="brand-lockup"><span>wanderbook<span className="brand-dot">.</span></span></span></a>
 <nav className={mobile?'nav mobile-open':'nav'} aria-label="Main navigation">{[['Journal',BookOpen],['My map',MapIcon],['Passport',Stamp]].map(([text,Icon])=><button key={String(text)} className={tab===text?'nav-item active':'nav-item'} onClick={()=>navigate(String(text))}>{typeof Icon!=='string'&&<Icon size={16}/>}<span>{String(text)}</span></button>)}</nav>
 <div className="header-actions"><span className="private-label"><LockKeyhole size={12}/>{repository?'Device journal':name}</span>{tab!=='Journal'&&<button className="primary small" onClick={newMemory}><Plus size={17}/><span>New memory</span></button>}<button className="icon-btn mobile-menu" aria-label="Toggle navigation" onClick={()=>setMobile(!mobile)}><Menu size={22}/></button></div></header>
 {repository?<aside className="device-storage-note"><LockKeyhole size={12}/><span><strong>Saved on this device.</strong> Photos here do not sync.</span><button className="text-button" onClick={()=>{setBackupReady(false);setTransfer(true)}}><Cloud size={13}/> Move to cloud</button><a href={CLOUD_JOURNAL_URL}>Open synced journal <ArrowUpRight size={13}/></a></aside>:signedIn&&<aside className="cloud-storage-note" role="status"><Cloud size={14}/><span>{loading?'Opening your cloud journal…':error?'Sync needs attention.':syncing?'Syncing…':'Saved to your account. Available on your other devices.'}</span><button type="button" aria-label="Refresh cloud journal" disabled={loading||syncing||!!editor||backup||busy||creatingAlbum} onClick={()=>void refreshCloud()}><RefreshCw size={13} className={syncing?'spin':''}/> Refresh</button><a href="/signout-with-chatgpt?return_to=/" target="_top">Sign out</a></aside>}

 <main>{tab==='Journal'&&<TravelCover albums={albums} sample={demo} memories={source.length} photos={photoCount} places={places.length} onAdd={newMemory} onOpen={album=>setAlbumKey(album.key)} onStories={setStoryKey} onBrowse={browseAlbums} onSwitch={()=>switchDemo(!demo)}/>}

 {tab==='Journal'&&<StoriesShelf albums={albums} sample={demo} seen={seenStories} onOpen={setStoryKey} onAdd={newMemory}/>}
 {tab==='Journal'&&<PlaceAlbums albums={albums} sample={demo} loading={loading} onOpen={album=>setAlbumKey(album.key)} onAdd={newMemory} onCreate={()=>{if(!signedIn){newMemory();return}setCreatingAlbum(true)}}/>}
 <section id="collection" className="collection"><div className="collection-top"><div><h2>{tab==='Journal'?'Notes':tab==='My map'?'Your map':'Places visited'}</h2>{tab!=='Journal'&&<p className="section-intro">{tab==='My map'?'Open a pin to revisit a memory.':'Your saved places.'}</p>}</div><button className="text-button surprise" disabled={!source.length} onClick={()=>setSelected(source[Math.floor(Math.random()*source.length)])}><Shuffle size={15}/> Random <ArrowUpRight size={15}/></button></div>

 {tab!=='Journal'&&<div className="view-note"><div><span className={demo?'demo-dot':'live-dot'}/><strong>{demo?'Sample journal':'Your personal journal'}</strong><span className="view-hint">{demo?'Illustrative photos and stories.':loading?'Opening your journal…':`${name.split(' ')[0]}’s saved memories`}</span></div><button onClick={()=>switchDemo(!demo)}>{demo?'Open my journal':'View sample journal'}<ArrowRight size={14}/></button></div>}
 {!signedIn&&<div className="notice"><LockKeyhole size={18}/><span>Sign in with ChatGPT to save your own memories and photos.</span><a href="/signin-with-chatgpt?return_to=/" target="_top">Sign in <ArrowUpRight size={15}/></a></div>}
 {error&&<div className="error-box" role="alert">{error}<button onClick={()=>window.location.reload()}>Retry</button></div>}

 {tab==='Journal'&&<><div className="toolbar"><div className="category-tabs">{['All moments',...categories].map(c=>{const Icon=catIcons[c as Category]||Sparkles;return <button className={category===c?'category active':'category'} key={c} onClick={()=>setCategory(c)}><Icon size={15}/>{c}<span>{c==='All moments'?source.length:source.filter(e=>e.category===c).length}</span></button>})}</div><div className="toolbar-right"><button className={onlyFav?'icon-btn favorited':'icon-btn'} title="Show favorites" aria-label="Show favorites" aria-pressed={onlyFav} onClick={()=>setOnlyFav(!onlyFav)}><Heart size={18} fill={onlyFav?'currentColor':'none'}/></button><button className={filters?'filter-button selected':'filter-button'} onClick={()=>setFilters(!filters)} aria-expanded={filters}><SlidersHorizontal size={16}/> Filter</button><div className="layout-toggle"><button className={layout==='grid'?'active':''} onClick={()=>setLayout('grid')} aria-label="Grid view"><Grid2X2 size={16}/></button><button className={layout==='timeline'?'active':''} onClick={()=>setLayout('timeline')} aria-label="Timeline view"><List size={18}/></button></div></div></div>
 <div className="search-row"><div className="search-input"><Search size={17}/><input aria-label="Search memories" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Find a place, a feeling, a memory…"/>{query&&<button className="icon-btn" onClick={()=>setQuery('')} aria-label="Clear search"><X size={15}/></button>}</div><label className="sort-label">Sort by <select aria-label="Sort memories" value={sort} onChange={e=>setSort(e.target.value)}><option value="newest">Newest first</option><option value="oldest">Oldest first</option><option value="title">Title A–Z</option></select></label></div>
 {filters&&<div className="filter-panel"><label>Mood <select value={mood} onChange={e=>setMood(e.target.value)}><option>All moods</option>{moods.map(m=><option key={m}>{m}</option>)}</select></label><button className="text-button" onClick={()=>{setMood('All moods');setCategory('All moments');setOnlyFav(false);setQuery('')}}>Reset filters</button></div>}
 {loading&&!demo?<div className="empty-state"><LoaderCircle className="spin"/> Opening your journal…</div>:filtered.length?<div className={layout==='grid'?'memory-grid':'memory-timeline'}>{filtered.map((e,i)=><article className={'memory-card cat-'+e.category.split(' ')[0].toLowerCase()} key={e.id} style={{animationDelay:`${Math.min(i,8)*70}ms`}}><div className="card-image"><button className="card-image-button" onClick={()=>setSelected(e)} aria-label={`Read ${e.title}`}><img src={image(e)} alt={e.photos[0]?.caption||e.title} loading="lazy"/></button><span className="category-badge">{(()=>{const Icon=catIcons[e.category];return <Icon size={12}/>})()}{e.category}</span><button className={'card-heart '+(e.favorite?'is-favorite':'')} onClick={()=>favorite(e)} aria-label={e.favorite?'Remove from favorites':'Add to favorites'}><Heart size={16} fill={e.favorite?'currentColor':'none'}/></button><span className="photo-count"><Camera size={12}/>{e.photos.length}</span></div><div className="card-body"><div className="card-meta"><MapPin size={12}/>{e.location}<span>·</span>{dateLabel(e.date)}</div><button className="card-title" onClick={()=>setSelected(e)}><h3>{e.title}</h3><ArrowUpRight size={20}/></button></div></article>)}</div>:<div className="empty-state"><div className="empty-icon"><BookOpen size={32} strokeWidth={1}/></div><h3>{query||category!=='All moments'||onlyFav||mood!=='All moods'?'No memories on this trail.':'Your next chapter starts here.'}</h3><p>{query||onlyFav||category!=='All moments'||mood!=='All moods'?'Try another search or clear your filters.':'A photo, a place, a few words. That’s all it takes to begin.'}</p><button className="primary" onClick={newMemory}><Plus size={16}/> Add a memory</button></div>}
 <div className="collection-bottom"><span>{filtered.length} {filtered.length===1?'entry':'entries'}</span><button className="text-button" onClick={()=>window.scrollTo({top:0,behavior:'smooth'})}>Back to top <MoveUp size={13}/></button></div></>}

 {tab==='My map'&&<><WorldMap entries={source} onSelect={setSelected}/><div className="map-cards">{source.filter(e=>e.lat!==null&&e.lng!==null).map(e=><button key={e.id} onClick={()=>setSelected(e)}><img src={image(e)} alt=""/><span><strong>{e.location}</strong><small>{e.title}</small></span><ArrowUpRight size={17}/></button>)}</div>{source.some(e=>e.lat===null||e.lng===null)&&<p className="help-text">Add a map pin in a memory’s editor to see it on your map.</p>}</>}

 {tab==='Passport'&&<div className="passport"><div className="passport-intro"><Compass size={48} strokeWidth={1}/><div className="eyebrow">WANDERBOOK EXPLORER’S PASSPORT</div><h3>Leave a little<br/><em>piece of your heart.</em></h3><p>{countries.length} {countries.length===1?'country':'countries'} · {places.length} places · countless reasons to go</p><span className="passport-id">PERSONAL EDITION &nbsp; / &nbsp; {new Date().getFullYear()}</span></div><div className="stamps">{places.length?places.map((place,i)=>{const e=source.find(x=>x.location===place)!;return <button className={'travel-stamp stamp-'+i%3} key={place} onClick={()=>setSelected(e)} style={{transform:`rotate(${[-5,4,-2,6][i%4]}deg)`}}><span>MEMORIES COLLECTED</span><Mountain size={29} strokeWidth={1}/><strong>{place}</strong><small>{e.country||'Somewhere wonderful'}</small><span>{dateLabel(e.date)}</span></button>}):<div className="empty-state"><Stamp size={35}/><h3>Your passport is waiting.</h3><p>Your first memory becomes your first stamp.</p><button className="primary" onClick={newMemory}>Let’s go <ArrowRight size={16}/></button></div>}</div></div>}

 </section></main>

 <footer><span className="footer-wordmark">wanderbook.</span><div><button disabled={backup||(!entries.length&&!folders.length)} onClick={exportJournal}>{backup?<LoaderCircle className="spin" size={14}/>:<Download size={14}/>} Back up journal</button><button disabled={backup||!signedIn} onClick={()=>importRef.current?.click()}><Upload size={14}/> Restore backup</button></div><input ref={importRef} type="file" accept="application/json,.json" hidden onChange={e=>{if(e.target.files?.[0])importJournal(e.target.files[0])}}/></footer>

 {openAlbum&&<Modal onClose={()=>setAlbumKey(null)} label={`${openAlbum.place} photo album`} className="album-dialog"><AlbumContents album={openAlbum} onClose={()=>setAlbumKey(null)} onPhoto={(index,items)=>setLightbox({entry:items[index].entry,index,items,title:openAlbum.place})} onStory={entry=>{setAlbumKey(null);setSelected(entry)}} onAdd={()=>addAlbumPhotos(openAlbum)} onShare={!repository&&!demo?()=>{setSharing({place:openAlbum.place,country:openAlbum.country});setAlbumKey(null)}:undefined}/></Modal>}
 {sharing&&<ShareAlbum album={sharing} onClose={()=>setSharing(null)}/>}
 {creatingAlbum&&<CreateAlbum onClose={()=>setCreatingAlbum(false)} onCreate={createAlbum}/>}
 {transfer&&<Modal label="Move journal to cloud" onClose={()=>{if(!backup)setTransfer(false)}} className="create-album-modal"><div className="editor-heading"><div><div className="eyebrow green">ON EVERY DEVICE</div><h2>Move to your cloud journal</h2></div><button className="icon-btn" disabled={backup} onClick={()=>setTransfer(false)} aria-label="Close cloud transfer"><X size={22}/></button></div><div className="transfer-content"><p>Download your device journal, then import that file into your signed-in cloud journal. Your device copy stays here.</p><button className="primary" disabled={backup} onClick={async()=>{setBackupReady(await exportJournal())}}>{backup?<LoaderCircle className="spin" size={16}/>:<Download size={16}/>} {backup?'Preparing your photos…':'1. Download journal'}</button>{backupReady&&<a className="primary" href={CLOUD_JOURNAL_URL+'/?restore=1'} target="_blank" rel="noopener noreferrer">2. Open cloud journal <ArrowUpRight size={16}/></a>}<p className="help-text">Use the same ChatGPT account on your computer and phone.</p></div></Modal>}
 {restoring&&<Modal label="Import device journal" onClose={()=>{if(!backup)setRestoring(false)}} className="create-album-modal"><div className="editor-heading"><div><div className="eyebrow green">BRING YOUR PHOTOS ALONG</div><h2>Import your device journal</h2></div><button className="icon-btn" disabled={backup} onClick={()=>setRestoring(false)} aria-label="Close journal import"><X size={22}/></button></div><div className="transfer-content"><p>Choose the Wanderbook JSON file you downloaded. Your photos and albums will be saved to this account and available on your other devices.</p><button className="primary" disabled={backup} onClick={()=>importRef.current?.click()}>{backup?<LoaderCircle className="spin" size={16}/>:<Upload size={16}/>} {backup?'Uploading your journal…':'Choose journal file'}</button></div></Modal>}
 {selected&&<MemoryDetail entry={selected} onClose={()=>setSelected(null)} onEdit={()=>{if(selected.id.startsWith('sample')){newMemory();return}setPhotoFirst(false);setEditor(selected)}} onFavorite={()=>favorite(selected)} onDelete={()=>remove(selected)} busy={busy} onPhoto={i=>setLightbox({entry:selected,index:i})}/>}
 {editor&&<Editor entry={editor} photoFirst={photoFirst} onClose={()=>setEditor(null)} onSave={save}/>}
 {storyKey&&<StoryViewer key={storyKey} albums={albums} startKey={storyKey} onClose={()=>setStoryKey(null)} onSeen={markStorySeen} onAlbum={album=>{setStoryKey(null);setAlbumKey(album.key)}}/>}
 {lightbox&&<Lightbox value={lightbox} onClose={()=>setLightbox(null)} onChange={i=>setLightbox({...lightbox,index:i})}/>}
 {toast&&<div className="toast" role="status"><Compass size={18}/>{toast}<button aria-label="Dismiss notification" onClick={()=>setToast('')}><X size={15}/></button></div>}
 </>
}

function MemoryDetail({entry:e,onClose,onEdit,onFavorite,onDelete,onPhoto,busy}:{entry:Entry;onClose:()=>void;onEdit:()=>void;onFavorite:()=>void;onDelete:()=>void;onPhoto:(index:number)=>void;busy:boolean}){
 const [confirm,setConfirm]=useState(false);
 return <Modal onClose={onClose} label={e.title} className="detail-modal"><button className="modal-close floating" onClick={onClose} aria-label="Close memory"><X size={21}/></button><button className="detail-cover" onClick={()=>e.photos.length&&onPhoto(0)} aria-label="Open cover photo"><img src={image(e)} alt={e.photos[0]?.caption||e.title}/><span><Camera size={14}/> {e.photos.length} {e.photos.length===1?'photo':'photos'} · Open gallery</span></button><div className="detail-content"><div className="eyebrow green">{e.category} &nbsp; / &nbsp; {e.mood}</div><h2>{e.title}</h2><div className="detail-meta"><span><MapPin size={15}/>{e.location}{e.country?`, ${e.country}`:''}</span><span><CalendarDays size={15}/>{dateLabel(e.date,true)}</span></div>{e.trip&&<div className="trip-tag"><BookOpen size={14}/> Part of <strong>{e.trip}</strong></div>}<div className="detail-actions"><button className="secondary" onClick={onFavorite}><Heart size={15} fill={e.favorite?'currentColor':'none'}/>{e.favorite?'A favorite':'Keep as a favorite'}</button><button className="text-button" onClick={onEdit}>{e.id.startsWith('sample')?<Plus size={15}/>:<Pencil size={15}/>} {e.id.startsWith('sample')?'Write your own':'Edit memory'}</button></div><div className="story-text">{e.story||'Some memories don’t need many words.'}</div>{(e.rating>0||e.cost)&&<div className="food-note">{e.rating>0&&<span className="rating-display">{Array.from({length:5},(_,i)=><Star key={i} size={16} fill={i<e.rating?'currentColor':'none'}/>)}<small>{e.rating}/5 · My experience</small></span>}{e.cost&&<span>Spent <strong>{e.cost}</strong></span>}</div>}{e.photos.length>1&&<div className="detail-gallery">{e.photos.map((p,i)=><figure key={p.id}><button onClick={()=>onPhoto(i)} aria-label={`Open photo ${i+1}`}><img src={image(e,p)} alt={p.caption||e.title} loading="lazy"/></button>{p.caption&&<figcaption>{p.caption}</figcaption>}</figure>)}</div>}{e.lat!==null&&e.lng!==null&&<a className="map-link" href={`https://www.openstreetmap.org/?mlat=${e.lat}&mlon=${e.lng}#map=13/${e.lat}/${e.lng}`} target="_blank" rel="noopener noreferrer"><MapIcon size={19}/><span>Find this little corner of the world<small>{e.lat.toFixed(4)}°, {e.lng.toFixed(4)}°</small></span><ArrowUpRight size={20}/></a>}{!e.id.startsWith('sample')&&<div className="delete-row">{confirm?<><span>Delete this memory and its photos permanently?</span><button className="danger" disabled={busy} onClick={onDelete}>{busy?'Deleting…':'Yes, delete'}</button><button className="text-button" disabled={busy} onClick={()=>setConfirm(false)}>Keep it</button></>:<button className="text-button muted" onClick={()=>setConfirm(true)}><Trash2 size={14}/> Delete memory</button>}</div>}</div></Modal>
}

export function Lightbox({value,onClose,onChange}:{value:GalleryValue;onClose:()=>void;onChange:(i:number)=>void}){
 const {entry:e,index}=value;const items=value.items||e.photos.map(photo=>({entry:e,photo}));const current=items[index];const move=(d:number)=>onChange((index+d+items.length)%items.length);
 const sweep=useSweep({enabled:items.length>1,onStep:move});
 return <Modal onClose={onClose} label="Photo gallery" className="lightbox"><div onKeyDown={event=>{if(event.key==='ArrowRight'){event.preventDefault();sweep.step(1)}if(event.key==='ArrowLeft'){event.preventDefault();sweep.step(-1)}}}>
  <div className="lightbox-top"><span>{value.title||e.title} <small>{index+1} / {items.length}</small></span><button className="icon-btn" onClick={onClose} aria-label="Close gallery"><X size={24}/></button></div>
  <div className={'lightbox-image sweep-'+sweep.phase} {...sweep.props}>
   <div className="gallery-sweep-card sweep-card" style={sweep.style}><img key={`${current.entry.id}-${current.photo.id}`} draggable={false} src={image(current.entry,current.photo)} alt={current.photo.caption||current.entry.title}/></div>
   {items.length>1&&<><button className="gallery-arrow left" onClick={()=>sweep.step(-1)} aria-label="Previous photo"><ChevronLeft/></button><button className="gallery-arrow right" onClick={()=>sweep.step(1)} aria-label="Next photo"><ChevronRight/></button></>}
  </div><p>{current.photo.caption||current.entry.location}{items.length>1&&<small className="gallery-drag-hint">Drag or swipe to turn the page</small>}</p></div></Modal>
}

export function WorldMap({entries,onSelect,picker,onPick,caption,center,showLabels=false}:{entries:Entry[];onSelect?:(e:Entry)=>void;picker?:boolean;onPick?:(lat:number,lng:number)=>void;caption?:string;center?:{lat:number;lng:number};showLabels?:boolean}){
 const [paths,setPaths]=useState<string[]>([]),[zoom,setZoom]=useState(center?4:1),[pan,setPan]=useState({x:0,y:0});const drag=useRef<{x:number;y:number;px:number;py:number}|null>(null);const moved=useRef(false);const svgRef=useRef<SVGSVGElement>(null);
 useEffect(()=>{let active=true;fetch(assetUrl('/world.json')).then(r=>r.json() as Promise<{features:{geometry:{type:string;coordinates:number[][][]|number[][][][]}}[]}>).then(data=>{const paths:string[]=[];for(const f of data.features){const polys=(f.geometry.type==='MultiPolygon'?f.geometry.coordinates:[f.geometry.coordinates]) as number[][][][];for(const poly of polys){paths.push(poly.map((ring:number[][])=>ring.map(([lon,lat],i)=>`${i?'L':'M'}${(lon+180)*2},${(90-lat)*2}`).join(' ')+'Z').join(' '))}}if(active)setPaths(paths)}).catch(()=>{});return()=>{active=false}},[]);
 useEffect(()=>{setZoom(center?4:1);setPan({x:0,y:0})},[center?.lat,center?.lng]);
 const pins=entries.filter(e=>e.lat!==null&&e.lng!==null);const scale=zoom;
 const offset={x:pan.x-(center?.lng??0)*2*scale,y:pan.y+(center?.lat??0)*2*scale};
 function pick(event:React.MouseEvent<SVGSVGElement>){if(!picker||!onPick||moved.current)return;const svg=svgRef.current!;const pt=svg.createSVGPoint();pt.x=event.clientX;pt.y=event.clientY;const matrix=svg.getScreenCTM();if(!matrix)return;const point=pt.matrixTransform(matrix.inverse());const x=(point.x-360-offset.x)/scale+360;const y=(point.y-180-offset.y)/scale+180;onPick(Math.max(-90,Math.min(90,90-y/2)),Math.max(-180,Math.min(180,x/2-180)))}
 return <div className={'world-map '+(picker?'picker-map':'')}><div className="map-label"><Globe2 size={15}/>{picker?'CLICK TO DROP YOUR PIN':'YOUR LITTLE CORNERS OF THE WORLD'}</div><svg ref={svgRef} viewBox="0 0 720 360" role="img" aria-label={picker?'World map. Click to set location, or enter coordinates below.':'World map of your memories. Select a location pin to read a story.'} onClick={pick} onPointerDown={e=>{if(picker||(e.target as Element).closest('[data-pin]'))return;drag.current={x:e.clientX,y:e.clientY,px:pan.x,py:pan.y};moved.current=false;e.currentTarget.setPointerCapture(e.pointerId)}} onPointerMove={e=>{if(!drag.current)return;const rect=e.currentTarget.getBoundingClientRect();const dx=(e.clientX-drag.current.x)*720/rect.width;const dy=(e.clientY-drag.current.y)*360/rect.height;if(Math.abs(dx)+Math.abs(dy)>3)moved.current=true;setPan({x:drag.current.px+dx,y:drag.current.py+dy})}} onPointerUp={()=>{drag.current=null}}><defs><pattern id={picker?'picker-grid':'world-grid'} width="60" height="60" patternUnits="userSpaceOnUse"><path d="M60 0H0V60" fill="none" stroke="#d9e2d9" strokeWidth=".6"/></pattern></defs><rect width="720" height="360" fill={`url(#${picker?'picker-grid':'world-grid'})`}/><g transform={`translate(${360+offset.x} ${180+offset.y}) scale(${scale}) translate(-360 -180)`}>{paths.map((d,i)=><path key={i} d={d} fill="#c2d0bb" stroke="#f0f2e9" strokeWidth=".6"/>)}{pins.length>1&&!picker&&<path d={pins.map((e,i)=>`${i?'L':'M'}${(e.lng!+180)*2} ${(90-e.lat!)*2}`).join(' ')} stroke="#c28d57" fill="none" strokeWidth={1.5/scale} strokeDasharray={`${4/scale} ${4/scale}`}/>} {pins.map((e,i)=><g key={e.id} data-pin="true" transform={`translate(${(e.lng!+180)*2} ${(90-e.lat!)*2}) scale(${1/scale})`} className="map-pin" tabIndex={picker?-1:0} role="button" aria-label={e.location} onClick={ev=>{ev.stopPropagation();onSelect?.(e)}} onKeyDown={ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();onSelect?.(e)}}}><circle r="22" fill="transparent"/><circle r="12" fill="#254b3e" opacity=".13"/><circle r="6" fill="#254b3e" stroke="white" strokeWidth="2"/>{showLabels&&<text x="16" y="4" fill="#254b3e" stroke="#f8f7ef" strokeWidth="3" paintOrder="stroke" fontSize="12" fontWeight="600">{e.location}</text>}<title>{e.location} — {e.title}</title></g>)}</g></svg>{!picker&&<div className="map-controls"><button aria-label="Zoom in" onClick={()=>setZoom(z=>Math.min(8,z*1.5))}><Plus size={17}/></button><button aria-label="Zoom out" onClick={()=>setZoom(z=>Math.max(1,z/1.5))}>−</button><button aria-label="Reset map" onClick={()=>{setZoom(center?4:1);setPan({x:0,y:0})}}><LocateFixed size={17}/></button></div>}<div className="map-footer"><span>{picker?'Or use coordinates for an exact location.':caption||`${pins.length} pinned memories · Drag to explore · + to zoom`}</span><small>Natural Earth</small></div></div>
}

function CreateAlbum({onClose,onCreate}:{onClose:()=>void;onCreate:(folder:AlbumFolder)=>Promise<void>}){
 const [place,setPlace]=useState(''),[country,setCountry]=useState(''),[error,setError]=useState(''),[saving,setSaving]=useState(false);const close=()=>{if(!saving)onClose()};
 return <Modal label="Create album" onClose={close} className="create-album-modal"><form onSubmit={async event=>{event.preventDefault();if(saving)return;setSaving(true);try{const [folder]=mergeAlbumFolders([{place,country}]);await onCreate(folder)}catch(err){setError((err as Error).message)}finally{setSaving(false)}}}><div className="editor-heading"><div><div className="eyebrow green">YOUR NEXT PLACE</div><h2>Create an album</h2></div><button className="icon-btn" type="button" disabled={saving} onClick={close} aria-label="Close album creator"><X size={22}/></button></div><div className="editor-content"><label className="field">Album name<input autoFocus required maxLength={150} value={place} onChange={event=>setPlace(event.target.value)} placeholder="Panchpokhari"/></label><label className="field">Country (optional)<input maxLength={80} value={country} onChange={event=>setCountry(event.target.value)} placeholder="Nepal"/></label>{error&&<div className="error-box" role="alert">{error}</div>}</div><div className="editor-footer"><button className="secondary" type="button" disabled={saving} onClick={close}>Cancel</button><button className="primary" type="submit" disabled={saving}>{saving?<LoaderCircle className="spin" size={16}/>:<Plus size={16}/>} {saving?'Creating album...':'Create album'}</button></div></form></Modal>;
}

function Editor({entry,photoFirst=false,onClose,onSave}:{entry:Entry;photoFirst?:boolean;onClose:()=>void;onSave:(e:Entry)=>Promise<void>}){
 const [e,set]=useState<Entry>({...entry,photos:entry.photos.map(p=>({...p}))}),[saving,setSaving]=useState(false),[processing,setProcessing]=useState(false),[error,setError]=useState(''),[dirty,setDirty]=useState(false),[discard,setDiscard]=useState(false),[showMap,setShowMap]=useState(false),[dragging,setDragging]=useState(false);const fileRef=useRef<HTMLInputElement>(null);const urls=useRef<string[]>([]);
 const change=<K extends keyof Entry>(key:K,value:Entry[K])=>{set(prev=>({...prev,[key]:value}));setDirty(true)};
 useEffect(()=>()=>urls.current.forEach(u=>URL.revokeObjectURL(u)),[]);
 const close=()=>{if(saving||processing)return;if(dirty)setDiscard(true);else onClose()};
 const addPhotos=async(files:FileList|File[])=>{setError('');setProcessing(true);try{if(e.photos.length+files.length>24)throw Error('You can keep up to 24 photos in a memory.');const added:Photo[]=[];for(const file of Array.from(files)){if(!['image/jpeg','image/png','image/webp','image/avif'].includes(file.type))throw Error('Choose JPG, PNG, WebP, or AVIF photos.');if(file.size>25*1024*1024)throw Error('Choose photos smaller than 25 MB before compression.');const bitmap=await createImageBitmap(file);const ratio=Math.min(1,2200/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);canvas.getContext('2d')!.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise<Blob>((res,rej)=>canvas.toBlob(b=>b?res(b):rej(Error('Photo could not be processed.')),'image/jpeg',.88));if(blob.size>8*1024*1024)throw Error('That photo is too large. Try a smaller image.');const url=URL.createObjectURL(blob);urls.current.push(url);added.push({id:crypto.randomUUID(),caption:'',file:new File([blob],file.name.replace(/\.[^.]+$/,'.jpg'),{type:'image/jpeg'}),url})}change('photos',[...e.photos,...added])}catch(err){setError((err as Error).message)}finally{setProcessing(false)}};
 const reorder=(i:number,d:number)=>{const ps=[...e.photos];const other=i+d;if(other<0||other>=ps.length)return;[ps[i],ps[other]]=[ps[other],ps[i]];change('photos',ps)};
 const locate=()=>{if(!navigator.geolocation){setError('Your browser does not support location. Enter coordinates instead.');return}navigator.geolocation.getCurrentPosition(p=>{change('lat',Number(p.coords.latitude.toFixed(5)));change('lng',Number(p.coords.longitude.toFixed(5)));setShowMap(true)},()=>setError('Location was unavailable. You can drop a pin or enter coordinates.'),{timeout:10000})};
 const submit=async(ev:React.FormEvent)=>{ev.preventDefault();setError('');if(photoFirst&&!e.photos.length){setError('Choose at least one photo for this album.');return}if((e.lat===null)!==(e.lng===null)){setError('Enter both latitude and longitude, or leave both blank.');return}if(e.photos.reduce((sum,p)=>sum+(p.file?.size||0),0)>40*1024*1024){setError('Please keep each upload below 40 MB in total.');return}setSaving(true);try{await onSave(e)}catch(err){setError((err as Error).message)}finally{setSaving(false)}};
 return <Modal onClose={close} label={photoFirst?'Upload photos to '+entry.location:entry.title?'Edit memory':'Add a memory'} className="editor-modal"><form onSubmit={submit}><div className="editor-heading"><div><div className="eyebrow green">A MOMENT WORTH KEEPING</div><h2>{photoFirst?'Photos for '+entry.location:entry.title?'Polish your story.':'Where did life take you?'}</h2><p>{photoFirst?'Choose your photos, check the date, and save.':'A few photos, a little story. Make it yours.'}</p></div><button className="icon-btn" type="button" onClick={close} aria-label="Close editor"><X size={22}/></button></div><div className="editor-content"><div className={'upload-zone '+(dragging?'dragging':'')} onDragOver={ev=>{ev.preventDefault();setDragging(true)}} onDragLeave={()=>setDragging(false)} onDrop={ev=>{ev.preventDefault();setDragging(false);if(!processing&&!saving)addPhotos(ev.dataTransfer.files)}}><ImagePlus size={31} strokeWidth={1.2}/><strong>{processing?'Making room for your moments…':'Drop your favorite moments here'}</strong><span>JPG, PNG, WebP, AVIF · Up to 24 photos · Automatically resized</span><button className="secondary" type="button" disabled={processing||saving} onClick={()=>fileRef.current?.click()}>{processing?<LoaderCircle size={15} className="spin"/>:<Plus size={15}/>} Choose photos</button><input hidden ref={fileRef} type="file" multiple accept="image/jpeg,image/png,image/webp,image/avif" onChange={ev=>{if(ev.target.files)addPhotos(ev.target.files);ev.target.value=''}}/></div>{!!e.photos.length&&<div className="edit-photo-list">{e.photos.map((p,i)=><div key={p.id} className="edit-photo"><div className="edit-photo-image"><img src={image(e,p)} alt={`Photo ${i+1}`}/>{i===0&&<span>Cover photo</span>}</div><div><input aria-label={`Caption for photo ${i+1}`} placeholder="A little caption…" value={p.caption} maxLength={300} onChange={ev=>change('photos',e.photos.map(x=>x.id===p.id?{...x,caption:ev.target.value}:x))}/><div className="photo-controls"><button type="button" disabled={i===0} onClick={()=>reorder(i,-1)} aria-label="Move photo earlier"><MoveUp size={14}/></button><button type="button" disabled={i===e.photos.length-1} onClick={()=>reorder(i,1)} aria-label="Move photo later"><MoveDown size={14}/></button>{i>0&&<button type="button" onClick={()=>change('photos',[p,...e.photos.filter(x=>x.id!==p.id)])}>Make cover</button>}<button type="button" onClick={()=>change('photos',e.photos.filter(x=>x.id!==p.id))} aria-label={`Remove photo ${i+1}`}><Trash2 size={14}/></button></div></div></div>)}</div>}
 <label className="field">Give your memory a name <span>*</span><input required maxLength={120} value={e.title} onChange={ev=>change('title',ev.target.value)} placeholder="That morning above the clouds…"/></label><div className="form-grid"><label className="field">Where were you? <span>*</span><input required maxLength={150} value={e.location} onChange={ev=>change('location',ev.target.value)} placeholder="Annapurna Base Camp"/></label><label className="field">Country<input value={e.country} maxLength={80} onChange={ev=>change('country',ev.target.value)} placeholder="Nepal"/></label><label className="field">When was it? <span>*</span><input type="date" required value={e.date} onChange={ev=>change('date',ev.target.value)}/></label><label className="field">Part of a trip<input value={e.trip} maxLength={120} onChange={ev=>change('trip',ev.target.value)} placeholder="My Himalayan adventure"/></label></div><fieldset className="category-field"><legend>What kind of moment?</legend><div>{categories.map(c=>{const Icon=catIcons[c];return <button type="button" className={e.category===c?'selected':''} key={c} onClick={()=>change('category',c)}><Icon size={17}/>{c}</button>})}</div></fieldset><label className="field">Tell the story<textarea rows={6} value={e.story} maxLength={20000} onChange={ev=>change('story',ev.target.value)} placeholder="The little details you don’t want to forget. How it felt. What made you smile. The best thing you ate…"/></label><div className="form-grid"><label className="field">The feeling<select value={e.mood} onChange={ev=>change('mood',ev.target.value as Mood)}>{moods.map(m=><option key={m}>{m}</option>)}</select></label><label className="field">What did you spend?<input maxLength={60} value={e.cost} onChange={ev=>change('cost',ev.target.value)} placeholder="NPR 650 · optional"/></label></div><div className="rating-field"><span>Your experience</span><div>{[1,2,3,4,5].map(n=><button type="button" key={n} aria-label={`Rate ${n} stars`} aria-pressed={e.rating===n} onClick={()=>change('rating',e.rating===n?0:n)}><Star size={22} fill={e.rating>=n?'currentColor':'none'}/></button>)}</div><button type="button" className={'favorite-toggle '+(e.favorite?'active':'')} onClick={()=>change('favorite',!e.favorite)}><Heart size={17} fill={e.favorite?'currentColor':'none'}/>{e.favorite?'A favorite':'Mark as a favorite'}</button></div><div className="pin-section"><button type="button" className="text-button" onClick={()=>setShowMap(!showMap)}><MapPin size={16}/>{e.lat!==null?'Location pinned':'Add a map pin'} <ChevronDown size={15}/></button><button type="button" className="text-button" onClick={locate}><LocateFixed size={15}/> Use my location</button></div>{showMap&&<div className="location-picker"><p className="help-text">Drop a pin, enter exact coordinates, or choose a starting point.</p><div className="preset-locations">{[{name:'Kathmandu',lat:27.7172,lng:85.324},{name:'Pokhara',lat:28.2096,lng:83.9595},{name:'Annapurna',lat:28.5303,lng:83.878}].map(p=><button type="button" key={p.name} onClick={()=>{change('lat',p.lat);change('lng',p.lng)}}>{p.name}</button>)}</div><WorldMap entries={e.lat!==null&&e.lng!==null?[e]:[]} picker onPick={(lat,lng)=>{change('lat',Number(lat.toFixed(5)));change('lng',Number(lng.toFixed(5)))}}/><div className="form-grid"><label className="field">Latitude<input type="number" min={-90} max={90} step="any" value={e.lat??''} onChange={ev=>change('lat',ev.target.value===''?null:Number(ev.target.value))}/></label><label className="field">Longitude<input type="number" min={-180} max={180} step="any" value={e.lng??''} onChange={ev=>change('lng',ev.target.value===''?null:Number(ev.target.value))}/></label></div><button type="button" className="text-button" onClick={()=>{change('lat',null);change('lng',null)}}>Remove pin</button></div>}{error&&<div className="error-box" role="alert">{error}</div>}{discard&&<div className="discard-box"><strong>Leave this story for another day?</strong><p>Your unsaved changes will be lost.</p><button type="button" className="danger" onClick={onClose}>Discard changes</button><button type="button" className="secondary" onClick={()=>setDiscard(false)}>Keep writing</button></div>}</div><div className="editor-footer"><span><LockKeyhole size={13}/> Just for you. Saved privately.</span><button type="submit" className="primary" disabled={saving||processing}>{saving?<LoaderCircle className="spin" size={16}/>:<Check size={16}/>} {saving?'Saving your memory…':photoFirst?'Save photos':'Keep this memory'}</button></div></form></Modal>
}
